from mk import *
from lib import fbd
STRICT["on"] = True
import math
G = 6.67e-11; R = 6.4e6; g = 9.8; r = 60 * R; T = 27.3 * 86400
M1 = g * R * R / G; M2 = 4 * math.pi ** 2 * r ** 3 / (G * T * T)

E(id="bagrut-1995-q5", year=1995, label="1995 שאלה 5", topic="gravitation", sub="grav-kepler", diff=3,
  stem=r"נתונים: רדיוס כדור הארץ $R_E = 6.4 \times 10^6\,\text{m}$. המרחק בין מרכז כדור הארץ למרכז הירח גדול בערך פי שישים מרדיוס כדור הארץ. הירח מקיף את כדור הארץ ב-$27.3$ יממות. תאוצת הנפילה החופשית על פני כדור הארץ $9.8\,\text{m/s}^2$. קבוע הכבידה $G = 6.67 \times 10^{-11}\,\text{N}\cdot\text{m}^2/\text{kg}^2$.",
  parts=[
    P("א1", r"כתבו את המסה של כוכב לכת בעזרת הרדיוס שלו ותאוצת הנפילה החופשית על פניו.", choice([r"$M = \frac{gR^2}{G}$", r"$M = \frac{gR}{G}$", r"$M = \frac{GR^2}{g}$", r"$M = \frac{g}{GR^2}$"], 0), ["principle"], [
        S(r"כבידה על פני הכוכב", r"על הפנים כוח הכבידה הוא המשקל. המסה של הגוף מצטמצמת", r"mg = \frac{GMm}{R^2} \;\Rightarrow\; M = \frac{gR^2}{G}", eq=r"F = \frac{GMm}{r^2}"),
    ], r"$M = \frac{gR^2}{G}$", key=r"M=gR²/G"),
    P("א2", r"לפי הביטוי שמצאתם, מה מסת כדור הארץ?", num(M1, "kg", tol=1), ["principle"], [
        S(r"מציבים", r"את תאוצת הכובד, הרדיוס והקבוע", r"M = \frac{9.8 \cdot (6.4 \times 10^6)^2}{6.67 \times 10^{-11}} \approx 6.02 \times 10^{24}\,\text{kg}"),
    ], r"$\approx 6.02 \times 10^{24}\,\text{kg}$", key=r"ME=6.02×10^24 kg"),
    P("ב1", r"כתבו את המסה של כוכב לכת בעזרת זמן המחזור של לוויין שנע סביבו ורדיוס המסלול של הלוויין.", choice([r"$M = \frac{4\pi^2 r^3}{GT^2}$", r"$M = \frac{4\pi^2 r^2}{GT^2}$", r"$M = \frac{GT^2}{4\pi^2 r^3}$", r"$M = \frac{2\pi r^3}{GT}$"], 0), ["principle"], [
        S(r"משוואת כוחות בכיוון המרכז", r"כוח הכבידה נותן ללוויין את התאוצה אל המרכז. מציבים את המהירות לפי זמן המחזור, ומבודדים את המסה", r"\frac{GMm}{r^2} = m\,\frac{4\pi^2}{T^2}\,r \;\Rightarrow\; M = \frac{4\pi^2 r^3}{GT^2}", eq=r"F = \frac{GMm}{r^2},\qquad a_R = \omega^2 r"),
    ], r"$M = \frac{4\pi^2 r^3}{GT^2}$", key=r"M=4π²r³/(GT²)"),
    P("ב2", r"לפי הביטוי שמצאתם, מה מסת כדור הארץ, מהנתונים של הירח?", num(M2, "kg", tol=1), ["principle", "units"], [
        S(r"הנתונים של הירח", r"ממירים את המרחק למטרים ואת זמן המחזור לשניות", r"r = 60 \cdot 6.4 \times 10^6 = 3.84 \times 10^8\,\text{m},\qquad T = 27.3 \cdot 86400 \approx 2.36 \times 10^6\,\text{s}"),
        S(r"מציבים", r"בביטוי מהסעיף הקודם", r"M = \frac{4\pi^2 \cdot (3.84 \times 10^8)^3}{6.67 \times 10^{-11} \cdot (2.36 \times 10^6)^2} \approx 6.02 \times 10^{24}\,\text{kg}"),
    ], r"$\approx 6.02 \times 10^{24}\,\text{kg}$", key=r"ME=6.02×10^24 kg"),
    P("ג", r"בדף הנוסחאות כתוב שהאנרגיה הקינטית של לוויין במסלול מעגלי סביב כוכב היא $E_K = \frac{GMm}{2r}$. הוכיחו את הקשר, בלי להשתמש בביטוי לאנרגיה הכוללת.", OPEN, ["principle", "algebra"], [
        S(r"משוואת כוחות בכיוון המרכז", r"כוח הכבידה נותן את התאוצה אל המרכז. כופלים את שני האגפים ברדיוס", r"\frac{GMm}{r^2} = \frac{mv^2}{r} \;\Rightarrow\; mv^2 = \frac{GMm}{r}", eq=r"F = \frac{GMm}{r^2},\qquad a_R = \frac{v^2}{r}"),
        S(r"מחלקים בשתיים", r"האנרגיה הקינטית היא חצי ממכפלת המסה בריבוע המהירות", r"E_K = \tfrac{1}{2}mv^2 = \frac{GMm}{2r}", eq=r"E_k = \tfrac{1}{2}mv^2"),
    ], r"ממשוואת הכוחות $\frac{GMm}{r^2} = \frac{mv^2}{r}$, מחלקים בשתיים"),
  ],
  concepts=["מסת כוכב מתאוצת הנפילה", "מסת כוכב מנתוני לוויין", "החוק השלישי של קפלר", "אנרגיה קינטית של לוויין"],
  summary=r"שתי דרכים לשקול את כדור הארץ: מתאוצת הנפילה על פניו ומהתנועה של הירח, ושתיהן נותנות אותה תוצאה.",
  review="הנחה שלי.\nבסעיפים א1 ו-ב1 התלמיד בוחר את הביטוי הנכון מתוך ארבעה.\nמה לבדוק: רק לאשר.")
